/*
	VIOC_fortifications.sqf - agregado por tools/vio_build.py (copia configurada, no es del autor de la mision).
	Parche "fortifications". Parametro de lobby VIOC_FORTIFICATIONS: 0 = original, 1 = si (por defecto).
	Solo corre en el servidor (jugando solo o alojando la partida, tu PC es el servidor).

	1) Nido alrededor de cada estatica de pueblo (MG, AT y las AA/AT extra de military_sites_statics).
	   Server_SpawnTownDefense.sqf y Server_BuildDefense.sqf solo anotan la estatica en VIOC_FORT_QUEUE; aqui se
	   arma cada nido de una sola vez (sin pausas a mitad) y se reparte en el tiempo.
	   - Ametralladora: herradura de sacos terreros abierta por detras (3 variantes: 3 sacos curvos como en las
	     misiones de BI; curvo + 4 cortos; muro largo + 2 laterales).
	   - Antitanque: sacos terreros (2 variantes) y, en pueblos, a veces la red de camuflaje encima (como en las
	     misiones de BI), solo si hay sitio libre para sus 15 x 8 m.
	   - Antiaerea: anillo de 5 barreras H de 3 bloques, abierto por detras.
	   - Morteros: anillo de sacos curvos. Piezas grandes (ZU-23, canones, SAM, radar): anillo de barreras H de 5.
	   - En algunos pueblos (15 %), si la estatica es alta (boca del canon a 1-1.65 m) y el suelo es plano, va
	     dentro de un bunker pequeno de sacos terreros, mirando por la tronera (igual que en las misiones de BI).
	   - A veces, cajas de municion detras. Siempre las mismas en el mismo sitio (no cambian al recapturar).
	   Mapas boscosos (la misma lista de mundos que base_structures_style y units_extra_qav): sacos, barreras y bunker verdes y red
	   woodland. En el resto: color arena y red del bando.
	   Reglas: cada pieza mira hacia el arma; ninguna pieza queda por encima de la linea de tiro (se entierra lo
	   necesario o se omite); nada en calles ni en el agua; nada que choque con edificios, muros, rocas, arboles,
	   vehiculos u otras piezas (rayos contra la geometria); nada si la estatica esta en un techo o bajo techo.
	   Ciclo de vida: las piezas se borran cuando la mision borra la estatica (evento "Deleted", y un barrido cada
	   60 s por si acaso): al capturar el pueblo (la mision borra y crea las estaticas del nuevo dueno, que reciben
	   su propio nido) o cuando el recolector de basura retira la estatica destruida. No se guardan en la partida:
	   al cargar, la mision vuelve a crear las estaticas y estas vuelven a recibir su nido.
	2) Defensas de base: el mismo nido para las estaticas de base con dotacion automatica (las que compra la IA
	   comandante siempre la tienen, tambien al cargar la partida). La IA ademas orienta la estatica hacia afuera
	   de su base. En la base no hay redes ni bunkers, para no estorbar las salidas de las fabricas.
	3) Defensas reactivas, solo para un bando con comandante IA: si hay enemigos cerca de un pueblo propio (550 m)
	   o de su base (500 m mas alla del borde), la IA paga con el dinero del comandante (el mismo con que compra
	   sus defensas) una estatica de pueblo de su nacion, con su tirador y su nido, del lado por donde viene el
	   enemigo: antiaerea si hay aeronaves, antitanque si hay blindados, si no ametralladora. Precio = el de esa
	   estatica en el menu de defensas (o el calculo de la mision) +25 %. Nunca deja al comandante con menos de
	   VIOC_FORT_RX_RESERVE. Topes: 2 por pueblo, 3 en la base, 8 por bando, 120 s entre despliegues del mismo
	   sitio. No aparece a menos de 250 m de un jugador ni a su vista, ni a menos de 110 m de un enemigo, ni si el
	   enemigo ya esta a menos de 150 m (ya es tarde). Se retira sin reembolso 3 min despues de que no queden
	   enemigos cerca (o a los 40 min), nunca a menos de 250 m de un jugador; se borra al perder el pueblo, como
	   las estaticas de la mision. No se guarda en la partida.
	Los sacos, barreras y estaticas de este parche no se pueden quitar con la herramienta de quitar defensas
	(ni dan reembolso): llevan la variable vioc_fort.
	Consola del servidor: VIOC_FORT_DEBUG = true (avisos en el chat); VIOC_FORT_STATUS = [nidos, piezas, reactivas].
*/
if (!isServer) exitWith {};
if ((missionNamespace getVariable ["VIOC_FORTIFICATIONS", 1]) <= 0) exitWith {VIOC_FORT_QUEUE = []; diag_log "[VIOC fortifications] desactivado por el parametro de lobby"};
if (!isNil "VIOC_FORT_RUNNING") exitWith {};
VIOC_FORT_RUNNING = true;

//--- Ajustes
VIOC_FORT_DEBUG = false;            // true: avisos en el chat de todos al crear o retirar un nido reactivo
VIOC_FORT_BUNKER_CHANCE = 15;       // % de estaticas altas de pueblo dentro de un bunker pequeno (si cabe)
VIOC_FORT_NET_CHANCE_AT = 55;       // % de antitanques de pueblo con red de camuflaje (si cabe)
VIOC_FORT_NET_CHANCE_MG = 10;       // % de ametralladoras de pueblo con red de camuflaje (si cabe)
VIOC_FORT_CRATES_CHANCE = 45;       // % de nidos con cajas de municion detras
VIOC_FORT_RX = true;                // defensas reactivas de la IA comandante
VIOC_FORT_RX_PERIOD = 20;           // s entre revisiones
VIOC_FORT_RX_RANGE_TOWN = 550;      // m alrededor del centro del pueblo
VIOC_FORT_RX_RANGE_BASE = 500;      // m mas alla del borde de la base
VIOC_FORT_RX_TOO_CLOSE = 150;       // enemigo a menos de esto del pueblo (o del borde de la base): ya no despliega
VIOC_FORT_RX_MIN_ENEMY = 3;         // hombres enemigos minimos (o 1 blindado o 1 aeronave)
VIOC_FORT_RX_CAP_TOWN = 2;
VIOC_FORT_RX_CAP_BASE = 3;
VIOC_FORT_RX_CAP_SIDE = 8;
VIOC_FORT_RX_COOLDOWN = 120;        // s entre despliegues del mismo pueblo o base
VIOC_FORT_RX_RESERVE = 5000;        // el comandante IA nunca baja de este dinero por estas defensas
VIOC_FORT_RX_SURCHARGE = 1.25;      // precio de la estatica +25 % (tirador y sacos terreros)
VIOC_FORT_RX_CALM = 180;            // s sin enemigos cerca: se retira
VIOC_FORT_RX_MAXLIFE = 2400;        // s como maximo
VIOC_FORT_RX_PLAYER_SAFE = 250;     // m: no aparece ni desaparece tan cerca de un jugador

if (isNil "VIOC_FORT_QUEUE") then {VIOC_FORT_QUEUE = []};
VIOC_FORT_REG = [];                 // [estatica, piezas] de cada nido, para el barrido
VIOC_FORT_RXL = [];                 // reactivas: [sitio, "town"/"base", estatica, tirador, grupo, hora, bando, tipo]
VIOC_FORT_RX_LATER = [];            // tiradores sueltos que se borran cuando no haya jugadores cerca
VIOC_FORT_STATUS = [0, 0, 0];

//--- Clases. Mapas boscosos: la misma lista de mundos que base_structures_style (version verde).
VIOC_FORT_GREEN = (toLower worldName) in ["chernarus", "chernarus_summer", "chernarus_winter", "cup_chernarus_a3", "enoch", "tanoa", "sara", "saralite", "sara_dbe1", "woodland_acr", "bootcamp_acr", "provinggrounds_pmc", "porto", "intro", "eden", "cain", "abel", "noe", "gm_weferlingen_summer", "gm_weferlingen_winter", "cam_lao_nam", "vn_khe_sanh", "vn_the_bra", "stozec"];
VIOC_FORT_CLS = createHashMap;
{
	_x params ["_key", "_sand", "_green"];
	private _c = [_sand, _green] select VIOC_FORT_GREEN;
	if !(isClass (configFile >> "CfgVehicles" >> _c)) then {_c = _sand};
	if (isClass (configFile >> "CfgVehicles" >> _c)) then {VIOC_FORT_CLS set [_key, _c]};
} forEach [
	["ROUND", "Land_BagFence_Round_F", "Land_BagFence_01_round_green_F"],
	["SHORT", "Land_BagFence_Short_F", "Land_BagFence_01_short_green_F"],
	["LONG", "Land_BagFence_Long_F", "Land_BagFence_01_long_green_F"],
	["HB3", "Land_HBarrier_3_F", "Land_HBarrier_01_line_3_green_F"],
	["HB5", "Land_HBarrier_5_F", "Land_HBarrier_01_line_5_green_F"],
	["BUNKER", "Land_BagBunker_Small_F", "Land_BagBunker_01_small_green_F"],
	["CRATES", "Land_Pallet_MilBoxes_F", "Land_Pallet_MilBoxes_F"]
];
//--- Medidas de cada pieza (de los modelos): [medio largo, medio fondo, alto] en m
VIOC_FORT_DIMS = createHashMapFromArray [
	["ROUND", [1.43, 0.54, 0.92]], ["SHORT", [0.98, 0.26, 0.9]], ["LONG", [1.57, 0.26, 0.92]],
	["HB3", [1.77, 0.87, 1.55]], ["HB5", [2.89, 0.85, 1.6]], ["BUNKER", [2.6, 2.6, 2.52]],
	["CRATES", [0.8, 0.78, 0.9]], ["NET", [7.3, 4.15, 3]]
];
//--- Margen bajo la boca del canon por tipo (-1 = sin limite de altura: el mortero dispara hacia arriba)
VIOC_FORT_MARGIN = createHashMapFromArray [["MG", 0.12], ["AT", 0.12], ["AA", 0.3], ["BIG", 0.3], ["MORTAR", -1]];
VIOC_FORT_INFO = createHashMap;     // por clase de estatica: [medio ancho, medio largo, boca del canon en coordenadas del modelo]

VIOC_FORT_fnc_netClass = {
	params ["_side"];
	private _c = if (VIOC_FORT_GREEN) then {"CamoNet_wdl_F"} else {switch (_side) do {case west: {"CamoNet_BLUFOR_F"}; case east: {"CamoNet_OPFOR_F"}; default {"CamoNet_INDP_F"}}};
	if !(isClass (configFile >> "CfgVehicles" >> _c)) then {_c = "CamoNet_INDP_F"};
	if (isClass (configFile >> "CfgVehicles" >> _c)) then {_c} else {""}
};

VIOC_FORT_fnc_staticInfo = {
	params ["_s"];
	private _cls = typeOf _s;
	private _info = VIOC_FORT_INFO getOrDefault [_cls, []];
	if (_info isEqualTo []) then {
		(boundingBoxReal _s) params ["_p1", "_p2"];
		private _ex = ((abs (_p1 select 0)) max (abs (_p2 select 0))) min 6;
		private _ey = ((abs (_p1 select 1)) max (abs (_p2 select 1))) min 6;
		private _mp = [];
		private _tur = configProperties [configOf _s >> "Turrets", "isClass _x", true];
		if (count _tur > 0) then {
			private _gb = getText ((_tur select 0) >> "gunBeg");
			private _ge = getText ((_tur select 0) >> "gunEnd");
			private _mb = if (_gb != "") then {_s selectionPosition _gb} else {[0, 0, 0]};
			private _me = if (_ge != "") then {_s selectionPosition _ge} else {[0, 0, 0]};
			if !(_mb isEqualTo [0, 0, 0]) then {
				//--- altura del eje del arma: media de boca y recamara (si el canon reposa elevado, la boca sola da de mas)
				_mp = if (_me isEqualTo [0, 0, 0]) then {_mb} else {[_mb select 0, _mb select 1, ((_mb select 2) + (_me select 2)) / 2]};
			};
		};
		if (_mp isEqualTo []) then {_mp = [0, 0, (_p1 select 2) + 0.55 * ((_p2 select 2) - (_p1 select 2))]};
		_info = [_ex, _ey, _mp];
		VIOC_FORT_INFO set [_cls, _info];
	};
	_info
};

//--- Sin nido si la estatica esta en un techo, puente o muelle, en el agua o bajo techo
VIOC_FORT_fnc_canFortify = {
	params ["_s"];
	private _atl = getPosATL _s;
	if ((_atl select 2) > 0.6) exitWith {false};
	if (surfaceIsWater _atl) exitWith {false};
	private _asl = getPosASL _s;
	(count (lineIntersectsSurfaces [_asl vectorAdd [0, 0, 2.2], _asl vectorAdd [0, 0, 15], _s, objNull, true, 1, "GEOM", "NONE"])) == 0
};

//--- true si la pieza cabe: ni calles, ni agua, ni mucha pendiente, ni nada de geometria (edificios, muros,
//--- rocas, arboles, vehiculos, personas, otras estaticas o piezas de otro nido) ni techo o ramas encima.
//--- La propia estatica y su tirador no cuentan: la distancia a ella ya sale de su tamano real.
VIOC_FORT_fnc_clear = {
	params ["_c", "_dir", "_dims", "_own", "_s", "_maxDiff", "_gS"];
	_dims params ["_hx", "_hy", "_h"];
	private _cx = _c select 0;
	private _cy = _c select 1;
	if (surfaceIsWater [_cx, _cy]) exitWith {false};
	private _rx = cos _dir;
	private _ry = -(sin _dir);
	private _fx = sin _dir;
	private _fy = cos _dir;
	private _big = _hx > 2 || {_hy > 1.5};
	private _pts = [[_cx, _cy], [_cx + _rx * _hx, _cy + _ry * _hx], [_cx - _rx * _hx, _cy - _ry * _hx], [_cx + _fx * _hy, _cy + _fy * _hy], [_cx - _fx * _hy, _cy - _fy * _hy]];
	if (_big) then {
		{_pts pushBack [_cx + _rx * _hx * (_x select 0) + _fx * _hy * (_x select 1), _cy + _ry * _hx * (_x select 0) + _fy * _hy * (_x select 1)]} forEach [[1, 1], [1, -1], [-1, 1], [-1, -1]];
	};
	if ((_pts findIf {isOnRoad [_x select 0, _x select 1, 0]}) >= 0) exitWith {false};
	private _hs = _pts apply {getTerrainHeightASL _x};
	if (((selectMax _hs) - (selectMin _hs)) > _maxDiff) exitWith {false};
	if (abs ((_hs select 0) - _gS) > 1.2) exitWith {false};
	private _crew = crew _s;
	private _near = (nearestObjects [[_cx, _cy, 0], ["Man", "LandVehicle", "Air", "Ship", "StaticWeapon"], (_hx max _hy) + 0.6]) select {!(_x isEqualTo _s) && {!(_x in _crew)}};
	if (count _near > 0) exitWith {false};
	private _segs = [];
	private _pairs = [[1, 2], [3, 4]];
	if (_big) then {_pairs append [[5, 6], [6, 8], [8, 7], [7, 5]]};
	{
		private _z = _x;
		{
			_x params ["_a", "_b"];
			_segs pushBack [[(_pts select _a) select 0, (_pts select _a) select 1, (_hs select _a) + _z], [(_pts select _b) select 0, (_pts select _b) select 1, (_hs select _b) + _z]];
		} forEach _pairs;
	} forEach [0.35, ((_h * 0.75) min 1.8) max 0.6];
	_segs pushBack [[_cx, _cy, (_hs select 0) + 10], [_cx, _cy, (_hs select 0) + 0.2]];
	if (_big) then {
		for "_i" from 5 to 8 do {_segs pushBack [[(_pts select _i) select 0, (_pts select _i) select 1, (_hs select _i) + 8], [(_pts select _i) select 0, (_pts select _i) select 1, (_hs select _i) + 0.3]]};
	};
	private _ok = true;
	{
		private _hits = lineIntersectsSurfaces [_x select 0, _x select 1, _s, objNull, true, 6, "GEOM", "NONE"];
		if ((_hits findIf {
			private _o = _x select 2;
			private _po = _x select 3;
			!isNull _o && {!(_o in _own)} && {!(_po in _own)} && {!(_po isEqualTo _s)} && {!(_o in _crew)}
		}) >= 0) exitWith {_ok = false};
	} forEach _segs;
	_ok
};

//--- Crea una pieza. _mode "center": _c es el centro del modelo; "origin": _c es su posicion (como en el editor).
//--- _limit: tope de altura ASL (se entierra hasta quedar debajo; si quedaria mas del 70 % enterrada no se pone).
VIOC_FORT_fnc_spawnPiece = {
	params ["_cls", "_c", "_dir", "_mode", "_align", "_limit"];
	private _o = createVehicle [_cls, [_c select 0, _c select 1, 0], [], 0, "CAN_COLLIDE"];
	if (isNull _o) exitWith {objNull};
	_o allowDamage false;
	_o setDir _dir;
	_o setPosATL [_c select 0, _c select 1, 0];
	if (_mode isEqualTo "center") then {
		private _m = _o modelToWorld [0, 0, 0];
		private _dx = (_c select 0) - (_m select 0);
		private _dy = (_c select 1) - (_m select 1);
		if (((abs _dx) + (abs _dy)) > 0.05) then {_o setPosATL [(_c select 0) + _dx, (_c select 1) + _dy, 0]};
	};
	if (_align) then {
		private _up = surfaceNormal (getPosATL _o);
		private _fw = [sin _dir, cos _dir, 0];
		_fw = vectorNormalized (_fw vectorDiff (_up vectorMultiply (_fw vectorDotProduct _up)));
		_o setVectorDirAndUp [_fw, _up];
	};
	if (_limit > -1000) then {
		(boundingBoxReal _o) params ["_b1", "_b2"];
		private _zTop = _b2 select 2;
		private _hgt = _zTop - (_b1 select 2);
		private _top = selectMax ([[_b1 select 0, _b1 select 1], [_b1 select 0, _b2 select 1], [_b2 select 0, _b1 select 1], [_b2 select 0, _b2 select 1], [0, 0]] apply {(_o modelToWorldWorld [_x select 0, _x select 1, _zTop]) select 2});
		private _sink = _top - _limit;
		if (_sink > 0) then {
			if (_sink > 0.7 * _hgt) then {
				deleteVehicle _o;
				_o = objNull;
			} else {
				private _p = getPosATL _o;
				_o setPosATL [_p select 0, _p select 1, (_p select 2) - _sink];
			};
		};
	};
	if (!isNull _o) then {_o setVariable ["vioc_fort", true, true]};
	_o
};

//--- Plan del nido en coordenadas del frente: [clave, x (derecha), y (adelante), giro respecto al frente, regla,
//--- modo, grupo]. Grupo "B" = bunker (si se pone, no van los "S"); "S" = sacos/barreras/red; "X" = siempre.
//--- _ex/_ey = medio ancho/medio largo de la estatica: los sacos van en una elipse que la deja libre.
VIOC_FORT_fnc_plan = {
	params ["_role", "_ex", "_ey", "_muzH", "_seed", "_ctx"];
	private _out = [];
	private _town = _ctx isEqualTo "town";
	private _dg = sqrt ((_ex ^ 2) + (_ey ^ 2));
	private _Rs = ((_ex + 0.75) max 1.3) min 3;
	private _Rf = ((_ey + 0.6) max 1.45) min 3.2;
	private _el = {
		//--- [clave, rumbo, extra, giro, regla, grupo] -> pieza sobre la elipse (+ extra metros)
		params ["_k", "_b", "_e", "_o", "_r", "_g"];
		private _d = (sqrt (((_Rs * (sin _b)) ^ 2) + ((_Rf * (cos _b)) ^ 2))) + _e;
		[_k, _d * (sin _b), _d * (cos _b), _b + _o, _r, "center", _g]
	};
	private _ring = {
		//--- [clave, rumbo, radio, giro, regla, grupo] -> pieza sobre un circulo
		params ["_k", "_b", "_d", "_o", "_r", "_g"];
		[_k, _d * (sin _b), _d * (cos _b), _b + _o, _r, "center", _g]
	};
	switch (_role) do {
		case "MG";
		case "AT": {
			private _at = _role isEqualTo "AT";
			if (_town && {((_seed * 7) mod 100) < VIOC_FORT_BUNKER_CHANCE} && {_muzH > ([1.05, 0.95] select _at)} && {_muzH < 1.65} && {_ex < 1.1} && {_ey < 1.6}) then {
				_out pushBack ["BUNKER", 0, [-0.5, 0.3] select _at, 180, "free", "origin", "B"];
			};
			private _v = if (_at) then {_seed mod 2} else {_seed mod 3};
			private _list = [];
			if (_at) then {
				_list = if (_v == 0) then {
					[["LONG", 0, 0.15, 0], ["SHORT", -60, 0.1, 0], ["SHORT", 60, 0.1, 0], ["SHORT", -112, 0.25, 0], ["SHORT", 112, 0.25, 0]]
				} else {
					[["ROUND", 0, 0, 180], ["SHORT", -68, 0.2, 0], ["SHORT", 68, 0.2, 0]]
				};
			} else {
				if (_v == 0) then {_list = [["ROUND", 0, 0, 180], ["ROUND", -90, 0.1, 180], ["ROUND", 90, 0.1, 180]]};
				if (_v == 1) then {_list = [["ROUND", 0, 0, 180], ["SHORT", -62, 0.2, 0], ["SHORT", 62, 0.2, 0], ["SHORT", -115, 0.3, 0], ["SHORT", 115, 0.3, 0]]};
			};
			{_out pushBack ([_x select 0, _x select 1, _x select 2, _x select 3, "low", "S"] call _el)} forEach _list;
			if (!_at && {_v == 2}) then {
				_out pushBack ["LONG", 0, _Rf + 0.1, 0, "low", "center", "S"];
				_out pushBack ["SHORT", -(_Rs + 0.3), _Rf - 0.62, 90, "low", "center", "S"];
				_out pushBack ["SHORT", _Rs + 0.3, _Rf - 0.62, 90, "low", "center", "S"];
			};
			if (_town && {((_seed * 13 + 5) mod 100) < ([VIOC_FORT_NET_CHANCE_MG, VIOC_FORT_NET_CHANCE_AT] select _at)}) then {
				_out pushBack ["NET", 0, -0.5, 180, "free", "center", "S"];
			};
			if (((_seed * 17 + 3) mod 100) < VIOC_FORT_CRATES_CHANCE) then {_out pushBack (["CRATES", 205, 1.5, 20, "lowskip", "X"] call _el)};
		};
		case "AA": {
			private _R = ((_dg + 0.95) max 3) min 5.5;
			{_out pushBack (["HB3", _x, _R, 0, "low", "S"] call _ring)} forEach [0, -60, 60, -120, 120];
			if (((_seed * 17 + 3) mod 100) < VIOC_FORT_CRATES_CHANCE) then {_out pushBack (["CRATES", 180, _R + 1.8, 90, "lowskip", "X"] call _ring)};
		};
		case "MORTAR": {
			private _R = ((_dg + 0.7) max 2.2) min 3.6;
			{_out pushBack (["ROUND", _x, _R, 180, "free", "S"] call _ring)} forEach [0, -70, 70, -140, 140];
		};
		default {
			private _R = ((_dg + 0.95) max 4) min 9;
			{_out pushBack (["HB5", _x, _R, 0, "low", "S"] call _ring)} forEach ([[0, -60, 60], [0, -60, 60, -120, 120]] select _town);
		};
	};
	_out
};

//--- Arma el nido de una estatica (se llama sin pausas: isNil). Devuelve las piezas.
VIOC_FORT_fnc_build = {
	params ["_s", "_role", "_front", "_ctx", "_side"];
	if (isNull _s || {!alive _s} || {!isNil {_s getVariable "vioc_fort_objs"}}) exitWith {[]};
	_s setVariable ["vioc_fort_objs", []];
	if !([_s] call VIOC_FORT_fnc_canFortify) exitWith {[]};
	([_s] call VIOC_FORT_fnc_staticInfo) params ["_ex", "_ey", "_mp"];
	if (((_ex max _ey) > 2.4) && {_role in ["MG", "AT", "MORTAR"]}) then {_role = "BIG"};
	private _p0 = getPosATL _s;
	private _gS = getTerrainHeightASL _p0;
	private _muz = (_s modelToWorldWorld _mp) select 2;
	private _margin = VIOC_FORT_MARGIN getOrDefault [_role, 0.15];
	private _limit = if (_margin < 0) then {-10000} else {_muz - _margin};
	private _seed = (floor (((_p0 select 0) * 13.37) + ((_p0 select 1) * 7.91))) mod 100;
	private _plan = [_role, _ex, _ey, _muz - _gS, _seed, _ctx] call VIOC_FORT_fnc_plan;
	private _own = [];
	private _bunker = false;
	private _sf = sin _front;
	private _cf = cos _front;
	{
		_x params ["_key", "_lx", "_ly", "_dr", "_rule", "_mode", "_grp"];
		private _cls = if (_key isEqualTo "NET") then {[_side] call VIOC_FORT_fnc_netClass} else {VIOC_FORT_CLS getOrDefault [_key, ""]};
		if (_cls != "" && {!(_bunker && {_grp isEqualTo "S"})}) then {
			private _dims = VIOC_FORT_DIMS getOrDefault [_key, [1, 0.5, 1]];
			private _c = [(_p0 select 0) + _lx * _cf + _ly * _sf, (_p0 select 1) - _lx * _sf + _ly * _cf];
			private _lim = if (_rule isEqualTo "low") then {_limit} else {-10000};
			private _ax = (_dims select 0) * (cos (_front + _dr));
			private _ay = -((_dims select 0) * (sin (_front + _dr)));
			private _gMax = selectMax ([_c, [(_c select 0) + _ax, (_c select 1) + _ay], [(_c select 0) - _ax, (_c select 1) - _ay]] apply {getTerrainHeightASL _x});
			private _skipHigh = (_rule isEqualTo "lowskip") && {_limit > -1000} && {(_gMax + (_dims select 2)) > (_limit + 0.05)};
			private _maxDiff = switch (_key) do {case "NET": {1.2}; case "BUNKER": {0.6}; case "HB5": {0.8}; case "HB3": {0.7}; default {0.55}};
			//--- control barato antes de crear nada: si quedaria casi toda enterrada, no va
			if (!_skipHigh && {_lim < -1000 || {((_gMax + (_dims select 2)) - _lim) < (0.7 * (_dims select 2))}}) then {
				if ([_c, _front + _dr, _dims, _own, _s, _maxDiff, _gS] call VIOC_FORT_fnc_clear) then {
					private _o = [_cls, _c, _front + _dr, _mode, !(_key in ["BUNKER", "NET", "CRATES"]), _lim] call VIOC_FORT_fnc_spawnPiece;
					if (!isNull _o) then {
						_own pushBack _o;
						if (_grp isEqualTo "B") then {_bunker = true};
					};
				};
			};
		};
	} forEach _plan;
	_s setVariable ["vioc_fort_objs", _own];
	if (count _own > 0) then {
		_s addEventHandler ["Deleted", {{if (!isNull _x) then {deleteVehicle _x}} forEach ((_this select 0) getVariable ["vioc_fort_objs", []])}];
		VIOC_FORT_REG pushBack [_s, _own];
	};
	_own
};

//--- Trabajo de la cola: [estatica, "town"/"base", tipo de la mision, frente, bando]
VIOC_FORT_fnc_job = {
	params ["_s", "_ctx", "_k", "_front", "_side"];
	if (isNull _s || {!alive _s}) exitWith {};
	private _role = "MG";
	if (_ctx isEqualTo "town") then {
		private _kinds = if (_k isEqualType []) then {_k select {_x isEqualType ""}} else {[]};
		private _cls = typeOf _s;
		private _kk = "";
		{
			if (_cls in (missionNamespace getVariable [format ["CTI_%1_Defenses_%2", _side, _x], []])) exitWith {_kk = _x};
		} forEach _kinds;
		if (_kk isEqualTo "" && {count _kinds > 0}) then {_kk = _kinds select 0};
		_role = switch (toUpper _kk) do {
			case "AT";
			case "VIOC_AT": {"AT"};
			case "AA";
			case "VIOC_AA": {"AA"};
			case "MORTAR";
			case "ARTILLERY": {"MORTAR"};
			default {"MG"};
		};
	} else {
		if !(_k isEqualType "") then {_k = ""};
		_role = switch (toUpper _k) do {
			case "AT": {"AT"};
			case "AA": {"AA"};
			case "ARTY": {"MORTAR"};
			default {"MG"};   //--- SAM y RADAR: con defensa < 3 son ametralladoras; los grandes pasan a "BIG" por tamano
		};
	};
	[_s, _role, _front, _ctx, _side] call VIOC_FORT_fnc_build;
};

//--- ---------------------------------------- Defensas reactivas ----------------------------------------
VIOC_FORT_fnc_playerNear = {
	params ["_pos", "_r"];
	(allPlayers findIf {alive _x && {!(_x isKindOf "HeadlessClient_F")} && {(_x distance2D _pos) < _r}}) >= 0
};

VIOC_FORT_fnc_playerSees = {
	params ["_posASL"];
	private _pAGL = ASLToAGL _posASL;
	(allPlayers findIf {alive _x && {!(_x isKindOf "HeadlessClient_F")} && {(_x distance2D _pAGL) < 1300} && {([vehicle _x, "VIEW", _x] checkVisibility [eyePos _x, _posASL]) > 0.15}}) >= 0
};

//--- Centro y radio de la base (HQ desplegado y estructuras a menos de 400 m). [] si no tiene base.
VIOC_FORT_fnc_baseInfo = {
	params ["_side"];
	private _logic = _side call CTI_CO_FNC_GetSideLogic;
	private _list = (_side call CTI_CO_FNC_GetSideStructures) select {!isNull _x && {alive _x}};
	private _hq = _side call CTI_CO_FNC_GetSideHQ;
	private _anchor = objNull;
	if (!isNil "_hq" && {!isNull _hq} && {alive _hq} && {_logic getVariable ["cti_hq_deployed", false]}) then {
		_anchor = _hq;
		_list pushBack _hq;
	} else {
		if (count _list > 0) then {_anchor = _list select 0};
	};
	if (isNull _anchor) exitWith {[]};
	_list = _list select {(_x distance2D _anchor) < 400};
	private _cx = 0;
	private _cy = 0;
	{
		private _p = getPosATL _x;
		_cx = _cx + (_p select 0);
		_cy = _cy + (_p select 1);
	} forEach _list;
	private _c = [_cx / (count _list), _cy / (count _list), 0];
	private _r = 25;
	{_r = _r max ((_x distance2D _c) + 15)} forEach _list;
	[_c, _r min 220]
};

//--- Amenaza alrededor de un punto: [hombres, blindados?, aereos?, distancia del mas cercano, rumbo, rumbo aereo, unidades]
VIOC_FORT_fnc_threat = {
	params ["_c", "_r", "_side", "_airAll"];
	private _foes = [west, east, resistance, sideEnemy] - [_side];
	private _men = 0;
	private _armor = false;
	private _dmin = 1e9;
	private _sx = 0;
	private _sy = 0;
	private _seen = [];
	{
		if (alive _x && {(side _x) in _foes}) then {
			private _n = if (_x isKindOf "Man") then {1} else {{alive _x} count (crew _x)};
			if (_n > 0) then {
				_men = _men + _n;
				if (!(_x isKindOf "Man") && {(_x isKindOf "Tank") || {(getNumber (configOf _x >> "armor")) >= 150}}) then {_armor = true};
				_dmin = _dmin min (_x distance2D _c);
				private _p = getPosATL _x;
				_sx = _sx + (_p select 0) * _n;
				_sy = _sy + (_p select 1) * _n;
				_seen pushBack _x;
			};
		};
	} forEach (_c nearEntities [["Man", "Car", "Tank", "Motorcycle", "Ship", "StaticWeapon"], _r]);
	private _brg = if (_men > 0) then {_c getDir [_sx / _men, _sy / _men, 0]} else {-1};
	private _air = _airAll select {(_x distance2D _c) < (_r + 900)};
	private _airBrg = if (count _air > 0) then {_c getDir (_air select 0)} else {-1};
	[_men, _armor, count _air > 0, _dmin, _brg, _airBrg, _seen + _air]
};

//--- [clase, precio] de una estatica de pueblo de ese tipo para ese bando, o [] si no hay
VIOC_FORT_fnc_rxPick = {
	params ["_side", "_kind"];
	private _list = (missionNamespace getVariable [format ["CTI_%1_Defenses_%2", _side, _kind], []]) select {_x isEqualType "" && {isClass (configFile >> "CfgVehicles" >> _x)} && {(getNumber (configFile >> "CfgVehicles" >> _x >> "scope")) >= 1}};
	if (count _list == 0) exitWith {[]};
	private _cls = selectRandom _list;
	private _def = missionNamespace getVariable [format ["CTI_%1_%2", _side, _cls], []];
	private _price = -1;
	if (_def isEqualType [] && {count _def > 2} && {(_def select 2) isEqualType 0}) then {_price = _def select 2};
	if (_price <= 0) then {
		_price = [750, 3600, 7200] select ((["MG", "AT", "AA"] find _kind) max 0);
		if (!isNil "CTI_CO_FNC_GetCalculatedUnitsPrize" && {!isNil "CTI_ECONOMY_PRIZE_WEAPONS"}) then {
			private _m = [2.5, 12, 12] select ((["MG", "AT", "AA"] find _kind) max 0);
			private _calc = [CTI_ECONOMY_PRIZE_WEAPONS, [0, 1] select (_kind isEqualTo "AA"), false, _m] call CTI_CO_FNC_GetCalculatedUnitsPrize;
			if (!isNil "_calc" && {_calc isEqualType 0} && {_calc > 0}) then {_price = _calc};
