//--- Sitio para la estatica: suelo firme y casi plano, fuera de calles, sin techo, con vista al enemigo
VIOC_FORT_fnc_rxSpotOk = {
	params ["_p", "_b", "_foes"];
	if (surfaceIsWater _p || {isOnRoad _p} || {count (_p nearRoads 8) > 0}) exitWith {false};
	if (((surfaceNormal _p) select 2) < 0.96) exitWith {false};
	if ([_p, VIOC_FORT_RX_PLAYER_SAFE] call VIOC_FORT_fnc_playerNear) exitWith {false};
	if (count (_p nearEntities [["StaticWeapon"], 20]) > 0) exitWith {false};
	if (((_p nearEntities [["Man", "Car", "Tank"], 110]) findIf {alive _x && {(side _x) in _foes}}) >= 0) exitWith {false};
	private _pA = AGLToASL _p;
	if ([_pA vectorAdd [0, 0, 1.2]] call VIOC_FORT_fnc_playerSees) exitWith {false};
	if (count (lineIntersectsSurfaces [_pA vectorAdd [0, 0, 2], _pA vectorAdd [0, 0, 15], objNull, objNull, true, 1, "GEOM", "NONE"]) > 0) exitWith {false};
	private _eye = _pA vectorAdd [0, 0, 1.3];
	private _near = AGLToASL [(_p select 0) + 25 * (sin _b), (_p select 1) + 25 * (cos _b), 0];
	if (count (lineIntersectsSurfaces [_eye, _near vectorAdd [0, 0, 1.3], objNull, objNull, true, 1, "GEOM", "NONE"]) > 0) exitWith {false};
	private _far = AGLToASL [(_p select 0) + 160 * (sin _b), (_p select 1) + 160 * (cos _b), 0];
	!(terrainIntersectASL [_eye, _far vectorAdd [0, 0, 1.5]])
};

VIOC_FORT_fnc_rxSpot = {
	params ["_c", "_brg", "_d0", "_cls", "_foes"];
	private _res = [];
	{
		private _b = _brg + _x;
		{
			private _d = _x;
			private _p = [(_c select 0) + _d * (sin _b), (_c select 1) + _d * (cos _b), 0] findEmptyPosition [0, 12, _cls];
			if (count _p > 0) then {_p = [_p select 0, _p select 1, 0]};
			if (count _p > 0 && {[_p, _brg, _foes] call VIOC_FORT_fnc_rxSpotOk}) exitWith {_res = _p};
		} forEach [_d0, _d0 + 30, (_d0 - 25) max 25];
		if (count _res > 0) exitWith {};
	} forEach [0, 15, -15, 30, -30, 50, -50];
	_res
};

//--- Crea la estatica, su nido y su tirador, y cobra (se llama sin pausas: isNil). true si salio bien.
VIOC_FORT_fnc_rxDeploy = {
	params ["_side", "_site", "_type", "_kind", "_cls", "_p", "_brg", "_cost", "_seen"];
	private _sideID = _side call CTI_CO_FNC_GetSideID;
	private _st = createVehicle [_cls, _p, [], 0, "CAN_COLLIDE"];
	if (isNull _st) exitWith {false};
	_st setDir _brg;
	_st setPosATL [_p select 0, _p select 1, 0];
	_st setVectorUp (surfaceNormal _p);
	_st setVariable ["vioc_fort", true, true];
	_st addEventHandler ["killed", format ["[_this select 0, _this select 1, %1] spawn CTI_CO_FNC_OnUnitKilled;", _sideID]];
	[_st, _kind, _brg, "rx", _side] call VIOC_FORT_fnc_build;
	private _grp = createGroup [_side, true];
	if (isNull _grp) exitWith {deleteVehicle _st; false};
	private _cc = missionNamespace getVariable [format ["CTI_%1_Static", _side], ""];
	if !(_cc isEqualType "" && {isClass (configFile >> "CfgVehicles" >> _cc)}) then {_cc = missionNamespace getVariable [format ["CTI_%1_Soldier", _side], ""]};
	if !(_cc isEqualType "" && {isClass (configFile >> "CfgVehicles" >> _cc)}) exitWith {deleteVehicle _st; deleteGroup _grp; false};
	private _u = [_cc, _grp, [_p select 0, _p select 1, 0], _sideID] call CTI_CO_FNC_CreateUnit;
	if (isNil "_u" || {!(_u isEqualType objNull)} || {isNull _u}) exitWith {deleteVehicle _st; deleteGroup _grp; false};
	_u assignAsGunner _st;
	_u moveInGunner _st;
	_grp setBehaviour "AWARE";
	_grp setCombatMode "RED";
	_grp allowFleeing 0;
	{_grp reveal [_x, 1.5]} forEach _seen;
	[_side, -_cost] call CTI_CO_FNC_ChangeFundsCommander;
	_site setVariable ["vioc_rx_t", time];
	VIOC_FORT_RXL pushBack [_site, _type, _st, _u, _grp, time, _side, _kind];
	true
};

//--- Un bando con comandante IA: mira sus pueblos y su base y, si hace falta y le alcanza, despliega uno.
VIOC_FORT_fnc_rxSide = {
	params ["_side"];
	private _logic = _side call CTI_CO_FNC_GetSideLogic;
	if (isNull _logic || {!(_logic getVariable ["cti_ai_commander", false])}) exitWith {};
	private _sideID = _side call CTI_CO_FNC_GetSideID;
	private _foes = [west, east, resistance, sideEnemy] - [_side];
	private _all = VIOC_FORT_RXL select {(_x select 6) isEqualTo _side};
	if ((count _all) >= (2 * VIOC_FORT_RX_CAP_SIDE)) exitWith {};
	//--- solo cuentan las que funcionan (estatica y tirador vivos, tirador dentro)
	private _mine = _all select {(alive (_x select 2)) && {alive (_x select 3)} && {(vehicle (_x select 3)) isEqualTo (_x select 2)}};
	private _airAll = vehicles select {(_x isKindOf "Air") && {alive _x} && {(side _x) in _foes} && {((getPosATL _x) select 2) < 700} && {({alive _x} count (crew _x)) > 0}};
	private _sites = [];
	{
		if ((_x getVariable ["cti_town_sideID", -1]) isEqualTo _sideID) then {_sites pushBack [_x, "town", getPosATL _x, VIOC_FORT_RX_RANGE_TOWN, VIOC_FORT_RX_CAP_TOWN, 0]};
	} forEach CTI_Towns;
	private _b = [_side] call VIOC_FORT_fnc_baseInfo;
	if (count _b > 0) then {_sites pushBack [_logic, "base", _b select 0, VIOC_FORT_RX_RANGE_BASE + (_b select 1), VIOC_FORT_RX_CAP_BASE, _b select 1]};
	private _best = [];
	private _bestScore = 0;
	{
		_x params ["_site", "_type", "_c", "_r", "_cap", "_br"];
		private _t = [_c, _r, _side, _airAll] call VIOC_FORT_fnc_threat;
		_t params ["_men", "_armor", "_air", "_dmin", "_brg"];
		if (_men > 0 || {_air}) then {_site setVariable ["vioc_rx_threat", time]};
		if (_brg >= 0) then {_site setVariable ["vioc_rx_brg", _brg]};
		private _here = {(_x select 0) isEqualTo _site} count _mine;
		private _capNow = _cap min (1 + ([0, 1] select (_men >= 8)) + ([0, 1] select (_armor || _air)));
		if ((_men >= VIOC_FORT_RX_MIN_ENEMY || {_armor} || {_air}) && {_here < _capNow} && {(time - (_site getVariable ["vioc_rx_t", -100000])) >= VIOC_FORT_RX_COOLDOWN} && {_dmin >= (VIOC_FORT_RX_TOO_CLOSE + _br)}) then {
			private _score = _men + ([0, 6] select _armor) + ([0, 6] select _air) + ([0, 10] select (_type isEqualTo "base"));
			if (_score > _bestScore) then {
				_bestScore = _score;
				_best = [_site, _type, _c, _br, _t];
			};
		};
	} forEach _sites;
	if (_best isEqualTo [] || {(count _mine) >= VIOC_FORT_RX_CAP_SIDE}) exitWith {};
	_best params ["_site", "_type", "_c", "_br", "_t"];
	_t params ["_men", "_armor", "_air", "_dmin", "_brg", "_airBrg", "_seen"];
	private _funds = _side call CTI_CO_FNC_GetFundsCommander;
	if (isNil "_funds" || {!(_funds isEqualType 0)}) exitWith {};
	private _hasAA = ({((_x select 0) isEqualTo _site) && {(_x select 7) isEqualTo "AA"}} count _mine) > 0;
	private _order = [];
	if (_air && {!_hasAA}) then {_order pushBack "AA"};
	if (_armor) then {_order pushBack "AT"};
	_order pushBack "MG";
	private _pick = [];
	{
		private _pc = [_side, _x] call VIOC_FORT_fnc_rxPick;
		if (count _pc > 0 && {_funds >= ((_pc select 1) + VIOC_FORT_RX_RESERVE)}) exitWith {_pick = [_x, _pc select 0, _pc select 1]};
	} forEach _order;
	if (_pick isEqualTo []) exitWith {};
	_pick params ["_kind", "_cls", "_cost"];
	private _dir = _brg;
	if (_kind isEqualTo "AA" && {_airBrg >= 0}) then {_dir = _airBrg};
	if (_dir < 0) then {_dir = _site getVariable ["vioc_rx_brg", random 360]};
	private _d0 = if (_type isEqualTo "base") then {_br + 20} else {((_dmin * 0.3) max 45) min 140};
	if (_dmin > 1e8) then {_d0 = if (_type isEqualTo "base") then {(_br * 0.5) max 25} else {40}};
	private _p = [_c, _dir, _d0, _cls, _foes] call VIOC_FORT_fnc_rxSpot;
	if (_p isEqualTo []) exitWith {_site setVariable ["vioc_rx_t", time - (VIOC_FORT_RX_COOLDOWN / 2)]};
	private _ok = false;
	isNil {_ok = [_side, _site, _type, _kind, _cls, _p, _dir, _cost, _seen] call VIOC_FORT_fnc_rxDeploy};
	if (!_ok) then {_site setVariable ["vioc_rx_t", time]};
	if (_ok) then {
		private _where = if (_type isEqualTo "town") then {_site getVariable ["cti_town_name", "pueblo"]} else {"base"};
		diag_log format ["[VIOC fortifications] %1 despliega %2 (%3) en %4 por %5$ (enemigos: %6, blindados: %7, aire: %8)", _side, _kind, _cls, _where, _cost, _men, _armor, _air];
		if (VIOC_FORT_DEBUG) then {(format ["VIOC: %1 despliega %2 en %3 (%4$)", _side, _kind, _where, _cost]) remoteExec ["systemChat", 0]};
	};
};

//--- Retira las reactivas que ya no hacen falta (sin reembolso) y borra los tiradores sueltos
VIOC_FORT_fnc_rxCleanup = {
	private _keep = [];
	{
		_x params ["_site", "_type", "_st", "_u", "", "_t0", "_side", "_kind"];
		private _lost = (_type isEqualTo "town") && {!((_site getVariable ["cti_town_sideID", -1]) isEqualTo (_side call CTI_CO_FNC_GetSideID))};
		private _calm = (time - (_site getVariable ["vioc_rx_threat", 0])) > VIOC_FORT_RX_CALM;
		private _old = (time - _t0) > VIOC_FORT_RX_MAXLIFE;
		private _pos = if (!isNull _st) then {getPosATL _st} else {if (!isNull _u) then {getPosATL _u} else {[0, 0, 0]}};
		private _active = (alive _st) && {alive _u} && {(vehicle _u) isEqualTo _st};
		private _playerIn = (!isNull _st) && {({isPlayer _x} count (crew _st)) > 0};
		//--- se retira: si ya no existe, si se perdio el pueblo, o (sin jugadores cerca) si quedo sin tirador, hay calma o es vieja
		if (!_playerIn && {isNull _st || {_lost} || {(!_active || _calm || _old) && {!([_pos, VIOC_FORT_RX_PLAYER_SAFE] call VIOC_FORT_fnc_playerNear)}}}) then {
			if (!isNull _u && {alive _u}) then {
				if ([getPosATL _u, 200] call VIOC_FORT_fnc_playerNear) then {VIOC_FORT_RX_LATER pushBack _u} else {deleteVehicle _u};
			};
			if (!isNull _st) then {deleteVehicle _st};
			if (VIOC_FORT_DEBUG) then {(format ["VIOC: %1 retira %2 (%3)", _side, _kind, ["calma o sin tirador", "pueblo perdido"] select _lost]) remoteExec ["systemChat", 0]};
		} else {
			_keep pushBack _x;
		};
	} forEach VIOC_FORT_RXL;
	VIOC_FORT_RXL = _keep;
	VIOC_FORT_RX_LATER = VIOC_FORT_RX_LATER select {
		if (isNull _x || {!alive _x}) then {false} else {
			if ([getPosATL _x, 200] call VIOC_FORT_fnc_playerNear) then {true} else {deleteVehicle _x; false};
		};
	};
};

//--- Cola de nidos (la llenan los ganchos de la mision) y barrido de piezas huerfanas
[] spawn {
	private _sweep = time + 60;
	private _first = true;
	while {true} do {
		if (count VIOC_FORT_QUEUE > 0) then {
			if ((time - ((VIOC_FORT_QUEUE select 0) param [5, -10000])) < 1) then {
				sleep 0.25;
			} else {
				private _job = VIOC_FORT_QUEUE deleteAt 0;
				isNil {_job call VIOC_FORT_fnc_job};
				sleep 0.02;
			};
		} else {
			if (_first) then {
				_first = false;
				private _n = 0;
				{_n = _n + count (_x select 1)} forEach VIOC_FORT_REG;
				diag_log format ["[VIOC fortifications] %1 nidos con %2 piezas en %3 (%4)", count VIOC_FORT_REG, _n, worldName, ["arena", "verde"] select VIOC_FORT_GREEN];
			};
			sleep 1;
		};
		if (time > _sweep) then {
			_sweep = time + 60;
			isNil {
				VIOC_FORT_REG = VIOC_FORT_REG select {
					if (isNull (_x select 0)) then {{if (!isNull _x) then {deleteVehicle _x}} forEach (_x select 1); false} else {true};
				};
				private _n = 0;
				{_n = _n + count (_x select 1)} forEach VIOC_FORT_REG;
				VIOC_FORT_STATUS = [count VIOC_FORT_REG, _n, count VIOC_FORT_RXL];
			};
		};
	};
};

//--- Defensas reactivas de la IA comandante
[] spawn {
	waitUntil {sleep 2; !isNil "CTI_Towns"};
	sleep 60;
	while {true} do {
		sleep VIOC_FORT_RX_PERIOD;
		if (missionNamespace getVariable ["CTI_GameOver", false]) exitWith {};
		if (VIOC_FORT_RX) then {{[_x] call VIOC_FORT_fnc_rxSide} forEach [west, east]};
		call VIOC_FORT_fnc_rxCleanup;
	};
};

